from __future__ import annotations

import ast
import re
import tokenize
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
PACKAGE = ROOT / "ascitwin"

FORBIDDEN = (
    "reproduction of",
    "based on the paper",
    "re-implementation",
    "following the authors",
    "as described by",
    "generated by",
    "ai-assisted",
    "skeleton",
    "placeholder",
    "todo from paper",
    "comprehensive",
    "state-of-the-art",
    "cutting-edge",
    "seamlessly",
    "leveraging",
    "utilize",
    "delve",
    "holistic",
    "meticulously",
    "it's worth noting",
    "in conclusion",
)

EMOJI = re.compile("[\U0001f000-\U0001faff☀-➿]")


def _python_files() -> list[Path]:
    return sorted(PACKAGE.rglob("*.py"))


def test_sources_have_no_comments() -> None:
    for path in _python_files():
        with tokenize.open(path) as handle:
            for token in tokenize.generate_tokens(handle.readline):
                assert token.type != tokenize.COMMENT, f"{path} carries a comment"


def test_sources_have_no_docstrings() -> None:
    for path in _python_files():
        tree = ast.parse(path.read_text())
        for node in ast.walk(tree):
            if isinstance(node, ast.Module | ast.FunctionDef | ast.AsyncFunctionDef | ast.ClassDef):
                assert ast.get_docstring(node) is None, f"{path} carries a docstring"


def test_no_forbidden_phrases() -> None:
    targets = [*_python_files(), ROOT / "README.md", ROOT / "Makefile"]
    for path in targets:
        if not path.exists():
            continue
        text = path.read_text().lower()
        for phrase in FORBIDDEN:
            assert phrase not in text, f"{path} contains '{phrase}'"


def test_no_emoji() -> None:
    targets = [*_python_files(), ROOT / "README.md"]
    for path in targets:
        if not path.exists():
            continue
        assert EMOJI.search(path.read_text()) is None, f"{path} contains an emoji"
